import {ToolRegistry} from './registry.js';

// spec: specs/hal-engine-tool-input-validation/spec.md#12
it('names the enum constraint when rejecting an unsupported weather unit', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'weather',
      description: 'Weather lookup',
      inputSchema: {type: 'object', properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}}},
    },
    async () => 'forecast'
  );

  const response = await registry.execute('weather', {unit: 'private-unit'});

  expect(response.result).toMatch(/unit.*enum/);
  expect(response.result).not.toContain('private-unit');
});
EOF
